const D = { scale:1, energy:.6, hue:28, speed:1, density:.5, floppiness:.6, snout:.5, chub:.5, x:.5, y:.78, seed:0, pose:'auto', style:'ink', act:'walk' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const s = u * 0.0023 * P.scale;
const bt = K.beat * P.speed;
const am = .82 + .22*Math.sin(K.t*.31 + fr(6)*6);
const eAmp = P.energy*(.5 + .6*K.intensity)*am;
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + A.bass*.7);
S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
if (S.tp==null || K.t < S.tp) S.tp = K.t;
const dt = Math.min(.08, Math.max(0, K.t - S.tp)); S.tp = K.t;

const ACTS = {
  walk:  ['trot','sit','trot','headbang','trot','idle','zoomies','headbang'],
  chill: ['sit','idle','sit','trot','sit','idle','sit','trot'],
  hyper: ['zoomies','headbang','zoomies','trot','zoomies','headbang','trot','zoomies'] };
let pose = P.pose;
if (pose==='auto') pose = (ACTS[P.act]||ACTS.walk)[((K.section%8)+8)%8];

const st = ['ink','gesture','silhouette','blueprint','charcoal'].includes(P.style) ? P.style : 'ink';
const H = ((P.hue%360)+360)%360;
const chw = .82 + P.chub*.5;

// ── pose → motion parameters ─────────────────────────────
let strideRate=0, reach=0, liftH=0, bob=0, bx=0, sway=0, pitch=0, headKick=0,
    pant=0, tailRate=5, tailAmp=.5, rumpDrop=0, frontDrop=0, look=0, earTgt=0, tuckBack=false, face=1;
const phi = bt;

if (pose==='trot') {
  strideRate=1; reach=30; liftH=22; bob=12;
  sway = Math.sin(bt*Math.PI/4)*4; pitch = Math.sin(phi*Math.PI*2)*.03;
  tailRate=6; tailAmp=.55; earTgt = -Math.cos(phi*Math.PI*2)*.5;
  look = Math.sin(K.t*.6)*.05;
} else if (pose==='zoomies') {
  strideRate=2; reach=42; liftH=34; bob=16;
  bx = Math.sin(bt*Math.PI/2)*58*eAmp;
  face = Math.cos(bt*Math.PI/2) >= 0 ? 1 : -1;
  pitch = -face*Math.sin(bt*Math.PI/2)*.10; sway = 0;
  tailRate=13; tailAmp=.75; earTgt = -1.1*Math.abs(Math.sin(phi*Math.PI*2)) - .4;
  look = 0;
} else if (pose==='headbang') {
  strideRate=0; reach=0; liftH=0; bob=0;
  headKick = kick; frontDrop = kick*11; pitch = kick*.22;
  sway = Math.sin(bt*Math.PI)*3; bob = kick*5;
  tailRate=7; tailAmp=.5; earTgt = -kick*1.7; look=0;
} else if (pose==='sit') {
  strideRate=0; rumpDrop=44; tuckBack=true; pitch=-.09;
  pant = .5+.5*Math.sin(K.t*5); look = Math.sin(K.t*.5)*.16;
  bob = Math.sin(K.t*3)*3; sway = Math.sin(K.t*.8)*3;
  tailRate=5; tailAmp=.62; earTgt = Math.sin(K.t*1.3)*.22;
} else { // idle
  strideRate=0; sway = Math.sin(K.t*.9)*6; look = Math.sin(K.t*.4)*.18;
  bob = Math.sin(K.t*1.5)*3.5; pant = Math.max(0, Math.sin(K.t*.7))*.5;
  tailRate=4; tailAmp=.42; earTgt = Math.sin(K.t*1.1)*.16; pitch = Math.sin(K.t*.5)*.02;
}

// universal slow drift — guarantees evolution even when beat-locked motion aliases
bob += Math.sin(K.t*.53 + fr(2)*6)*3;
sway += Math.sin(K.t*.37 + fr(4)*6)*4;
pitch += Math.sin(K.t*.21 + fr(8)*6)*.02;

// stride-driven body bob (2 footfalls per stride)
const sp = phi*strideRate;
const gaitBob = strideRate>0 ? -Math.abs(Math.sin(sp*Math.PI*2))*bob*eAmp : bob*eAmp*.4;
const dy = gaitBob - headKick*0 - frontDrop*0;   // dy is body vertical

// ear floppy spring
if (S.ea==null){S.ea=0;S.ev=0;}
S.ev += (earTgt*(.4+P.floppiness) - S.ea)*.30; S.ev *= .74; S.ea += S.ev;
const earA = (.55 + P.floppiness*.95) + S.ea;

// tail wag accumulator (rate rises with treble)
S.wag = (S.wag||0) + dt*(tailRate*(1+.3*eAmp) + S.tre*30);
const tailSw = Math.sin(S.wag)*tailAmp*(.7+.6*eAmp);

const ax = P.x*width + (sway+bx)*s;
const ay = P.y*height;
const pump = 1 + S.rms*.28*P.energy + K.swell*.02*eAmp;

// ── style primitives ─────────────────────────────────────
function furStroke(h,sa,br,a){ a=a||100;
  if (st==='ink'){ fill(h, Math.min(34,sa*.42), 93, 46); stroke(28,36,24,92); strokeWeight(2.0); }
  else if (st==='gesture'){ noFill(); stroke(28,32,22,80); strokeWeight(2.8); }
  else if (st==='silhouette'){ noStroke(); fill(H,24,13,100); }
  else if (st==='blueprint'){ noFill(); stroke(205,58,100,72); strokeWeight(1.3); }
  else { noStroke(); drawingContext.shadowBlur=9; drawingContext.shadowColor='rgba(0,0,0,.55)'; fill(H,15,15,32); }
}
function blob(cx,cy,rx,ry,sb){
  const wob = (st==='ink'||st==='gesture')?.13:(st==='silhouette'?.04:.05);
  const n=16; beginShape();
  for(let k=-1;k<=n+1;k++){ const a=k/n*Math.PI*2; const rr=1+(fr(sb+((k%n)+n)%n)-.5)*wob*2;
    curveVertex(cx+Math.cos(a)*rx*rr, cy+Math.sin(a)*ry*rr); }
  endShape();
}
function limb(x1,y1,x2,y2,x3,y3,dark){
  if (st==='silhouette'){ stroke(H,24,dark?9:13,100); strokeWeight(13*chw); noFill(); strokeCap(ROUND); }
  else if (st==='charcoal'){ stroke(H,15,dark?9:15,dark?26:34); strokeWeight(11); noFill(); strokeCap(ROUND); drawingContext.shadowBlur=8; drawingContext.shadowColor='rgba(0,0,0,.4)'; }
  else if (st==='blueprint'){ stroke(205,58,100,dark?45:72); strokeWeight(1.3); noFill(); }
  else { stroke(28,36,dark?18:24,dark?70:92); strokeWeight(st==='gesture'?2.6:2.0); noFill(); strokeCap(ROUND); }
  beginShape(); curveVertex(x1,y1); curveVertex(x1,y1); curveVertex(x2,y2); curveVertex(x3,y3); curveVertex(x3,y3); endShape();
  drawingContext.shadowBlur=0;
}

function drawLeg(hx, hy, phase, dark, tuck){
  let fxo, foy;
  if (tuck){ fxo = hx*0.15; foy = hy + 10; }
  else { fxo = reach*Math.cos(phase*Math.PI*2); foy = -Math.max(0,Math.sin(phase*Math.PI*2))*liftH; }
  const footx = hx*chw*0.9 + fxo;
  const kx = (hx*chw + footx)/2 + 9*(dark?.6:1);
  const ky = (hy + foy)/2 + 2;
  limb(hx*chw, hy, kx, ky, footx, foy, dark);
  if (!dark && st!=='blueprint'){ // paw
    if (st==='silhouette'){ noStroke(); fill(H,24,13,100); }
    else if (st==='charcoal'){ noStroke(); fill(H,15,15,34); }
    else { noStroke(); fill(28,30,20,90); }
    ellipse(footx, foy-1, 12, 7);
  }
}

// ── assemble ─────────────────────────────────────────────
// ground shadow
noStroke(); fill(0,0,0,26);
ellipse(P.x*width, ay+4*s, (150 + Math.abs(bx)*1.4)*s*chw, 18*s);

push();
translate(ax, ay + dy*s);
scale(s*face*pump, s*pump);
rotate(pitch);

const backHipY = -70 + rumpDrop*(tuckBack?1:.3) - frontDrop*.2;
const frontHipY = -78 + frontDrop*.7;

// TAIL (behind) — wagging plume
push(); translate(-92*chw, -104 + rumpDrop*.5); rotate(-0.5 + tailSw);
if (st==='silhouette'){ noStroke(); fill(H,24,12,100); }
else if (st==='charcoal'){ noStroke(); fill(H,15,15,30); }
else if (st==='blueprint'){ noFill(); stroke(205,58,100,60); strokeWeight(1.2); }
else { fill(28,20,90,st==='ink'?40:0); if(st==='gesture')noFill(); stroke(28,36,24,88); strokeWeight(st==='gesture'?2.6:2.0); strokeCap(ROUND); }
beginShape(); curveVertex(0,0); curveVertex(0,0); curveVertex(-26,-8); curveVertex(-54,-30); curveVertex(-70,-58); curveVertex(-70,-58); endShape();
pop();

// far legs (darker, behind body)
drawLeg(-52, backHipY, phi+.5, true, tuckBack);
drawLeg(44, frontHipY, phi, true, false);

// BODY
furStroke(H, 70, 90); blob(-6, -108 - frontDrop*.15, 96*chw, 62*chw, 20);   // torso
furStroke(H, 66, 88); blob(-64, -104 + rumpDrop*.5, 54*chw, 54*chw, 40);    // rump
furStroke(H, 70, 92); blob(54, -114 + frontDrop*.4, 52*chw, 56*chw, 60);    // chest
if (st==='ink' || st==='charcoal'){ // belly tone
  noStroke(); fill(H,20,st==='ink'?99:16, st==='ink'?36:24); ellipse(-6,-84,120*chw,42);
}

// near legs (front)
drawLeg(-58, backHipY, phi, false, tuckBack);
drawLeg(52, frontHipY, phi+.5, false, false);

// NECK + HEAD
const hx0 = 88, hy0 = -172 - frontDrop*.2 + headKick*10;
push(); translate(hx0, hy0); rotate(look + headKick*.18 + Math.sin(K.t*2.4)*.02*eAmp);
// neck
if (st!=='silhouette' && st!=='charcoal'){ furStroke(H,70,90); }
else furStroke(H,70,90);
push(); rotate(-0.6); furStroke(H,68,88); blob(-30,44,34,26,110); pop();
// head
furStroke(H, 72, 93); blob(0, 0, 46*chw, 42, 130);
// snout / muzzle
const sn = 24 + P.snout*30;
furStroke(H, 68, 92); blob(38 + sn*.4, 14, sn*.6, 20, 150);
// nose
if (st==='silhouette'){ noStroke(); fill(H,24,12,100); }
else if (st==='blueprint'){ noFill(); stroke(205,58,100,80); strokeWeight(1.2); }
else if (st==='charcoal'){ noStroke(); fill(0,0,8,60); drawingContext.shadowBlur=6; drawingContext.shadowColor='rgba(0,0,0,.5)'; }
else { noStroke(); fill(0,0,12,95); }
ellipse(40 + sn*.72, 12, 13, 10); drawingContext.shadowBlur=0;
// mouth / pant tongue
if (st!=='silhouette'){
  stroke(st==='blueprint'?color(205,58,100,70):color(28,36,20,80)); strokeWeight(1.4); noFill();
  const mo = pant*6;
  line(30, 22, 46+sn*.4, 22+mo);
  if (pant>.2 && st!=='blueprint' && st!=='charcoal'){ noStroke(); fill(350,55,95,85); ellipse(44+sn*.35, 26+mo, 9, 11); }
}
// eye
if (st!=='silhouette'){
  if (st==='blueprint'){ stroke(205,58,100,85); strokeWeight(1.2); noFill(); line(10,-8,22,-8); line(16,-14,16,-2); }
  else { noStroke(); fill(st==='charcoal'?color(0,0,90,50):color(0,0,12,95)); const gz=Math.sin(K.t*.5)*2;
    ellipse(15+gz, -6, 11, 12); if(st!=='charcoal'){ fill(0,0,100,90); circle(17+gz,-8,3.5); } }
}
// EARS (floppy, hinged back-top of head)
for (let side=0; side<2; side++){
  const sgn = side===0 ? 1 : 1; // both drop same side in profile; second is far ear
  const far = side===1;
  push(); translate(-14, -22); rotate(earA + (far?.12:0));
  if (st==='silhouette'){ noStroke(); fill(H,24, far?9:13,100); }
  else if (st==='charcoal'){ noStroke(); fill(H,16, far?10:16, far?24:32); drawingContext.shadowBlur=7; drawingContext.shadowColor='rgba(0,0,0,.4)'; }
  else if (st==='blueprint'){ noFill(); stroke(205,58,100, far?45:72); strokeWeight(1.3); }
  else { fill(H,55, far?70:82, st==='ink'?55:0); if(st==='gesture'||st==='blueprint')noFill(); stroke(28,36, far?18:24,90); strokeWeight(2.0); }
  beginShape(); curveVertex(0,0); curveVertex(0,0); curveVertex(-10,26); curveVertex(-6,56*(.7+P.floppiness*.5)); curveVertex(10,44); curveVertex(8,10); curveVertex(8,10); endShape(CLOSE);
  drawingContext.shadowBlur=0;
  pop();
}
pop(); // head

// ink hatching under belly for tone
if (st==='ink'){
  stroke(28,36,24,34); strokeWeight(1.1);
  for(let i=0;i<7;i++){ const o=(fr(i+200)-.5)*70; line(-50+o,-70, -34+o,-52); }
  noStroke();
}
// blueprint construction marks
if (st==='blueprint'){
  stroke(205,50,100,30); strokeWeight(.8); noFill();
  ellipse(-6,-108,200*chw,140*chw); line(-140,-40,150,-40);
  for(let i=-6;i<=6;i++){ line(i*22,-38,i*22,-44); }
  noStroke();
}
pop(); // body

drawingContext.shadowBlur=0;
// ambient — dust motes drifting (density), sparkle on treble
const nD = Math.floor(P.density*10);
blendMode(ADD); noStroke();
for(let i=0;i<nD;i++){
  const q=fr(i+300), q2=fr(i+340);
  const dx=(q-.5)*260*s, dyy=Math.sin(K.t*.5+q*6)*40*s - 40*s;
  fill(H,20,100, 8 + S.tre*40*q2 + 8*Math.abs(Math.sin(K.t*1.2+q*6)));
  circle(ax+dx, ay-90*s+dyy, (1.4+q2*1.6)*s);
}
blendMode(BLEND);
